1230          p = (uint8_t *) q;
  1231          q += slen;
  1232
  1233          while ((current < after) && (*current != 0x00)) {
  1234                  /*
  1235                   *      Get how many bytes this label has, and where
  1236                   *      we will go to obtain the next label.
  1237                   *
  1238                   *      Note that slen > 0 here, as dns_label_decode()
  1239                   *      only returns 0 when the current byte is 0x00,
  1240                   *      which it can't be.
  1241                   */
  1242                  slen = dns_label_decode(packet, &current, &next);
  1243
  1244                  /*
  1245                   *      As a sanity check, ensure we don't have a
  1246                   *      buffer overflow.
  1247                   */
  1248                  if ((p + slen) > (uint8_t *) q) {
  1249                          FR_PROTO_TRACE("dns_label_to_value_box - length %zd Failed at %d", slen, __LINE__);
  1250
  1251                  fail:
  1252                          fr_value_box_clear(dst);
  1253                          return -1;
  1254                  }
  1255
  1256                  /*
  1257                   *      Add '.' before the label, but only for the
  1258                   *      second and subsequent labels.
  1259                   */
  1260                  if (p != (uint8_t const *) dst->vb_strvalue) {
  1261                          *(p++) = '.';
  1262                  }
  1263
  1264                  /*
  1265                   *      Copy the raw bytes from the network.
  1266                   */
  1267                  memcpy(p, current + 1, slen);
  1268
  1269                  /*
  1270                   *      Go ahead in the output string, and go to the
  1271                   *      next label for decoding.
  1272                   */
  1273                  p += slen;
  1274                  current = next;
  1275          }
  1276
  1277          /*
  1278           *      As a last sanity check, ensure that we've filled the
  1279           *      buffer exactly.
  1280           */
  1281          if (p != (uint8_t *) q) {
  1282                  FR_PROTO_TRACE("dns_label_to_value_box - Failed at %d", __LINE__);
  1283                  goto fail;
  1284          }
  1285
  1286          *p = '\0';
  1287
  1288          /*
  1289           *      Return the number of network bytes used to parse this
  1290           *      part of the label.
  1291           */
  1292          return after - label;
  1293  }
