    42  static ssize_t decode_raw(TALLOC_CTX *ctx, fr_dcursor_t *cursor, UNUSED fr_dict_t const *dict,
    43                            fr_dict_attr_t const *parent,
    44                            uint8_t const *data, size_t const data_len, void *decode_ctx)
    45  {
    46          fr_pair_t               *vp;
    47          fr_dict_attr_t          *unknown;
    48          fr_dict_attr_t const    *da;
    49          fr_dns_ctx_t    *packet_ctx = decode_ctx;
    50          ssize_t                 slen;
    51
    52  #ifdef __clang_analyzer__
    53          if (!packet_ctx || !packet_ctx->tmp_ctx || !parent->parent) return PAIR_DECODE_FATAL_ERROR;
    54  #endif
    55
    56          FR_PROTO_HEX_DUMP(data, data_len, "decode_raw");
    57
    58          /*
    59           *      Re-write the attribute to be "raw".  It is
    60           *      therefore of type "octets", and will be
    61           *      handled below.
    62           */
    63          unknown = fr_dict_unknown_attr_afrom_da(packet_ctx->tmp_ctx, parent);
    64          if (!unknown) {
    65                  fr_strerror_printf("%s: Internal sanity check %d", __FUNCTION__, __LINE__);
    66                  return PAIR_DECODE_OOM;
    67          }
    68          unknown->flags.is_raw = 1;
    69
    70          vp = fr_pair_afrom_da(ctx, unknown);
    71          if (!vp) return PAIR_DECODE_OOM;
    72
    73          slen = fr_value_box_from_network(vp, &vp->data, vp->da->type, vp->da,
    74                                           &FR_DBUFF_TMP(data, data_len), data_len, true);
    75          if (slen < 0) {
    76                  talloc_free(vp);
    77                  da = unknown;
    78                  fr_dict_unknown_free(&da);
    79                  return slen;
    80          }
    81
    82          vp->type = VT_DATA;
    83          vp->vp_tainted = true;
    84          fr_dcursor_append(cursor, vp);
    85          return data_len;
    86  }
